// The game reports each finished run through the bridge - read it here.
const run = nb.get('snake_last_run');
const best = nb.get('snake_high_score');
if (!run) return 'Play a game first (click the board, arrows/WASD), then re-run this cell.';

console.log('last run:', JSON.stringify(run));
console.log('high score:', best);

const applesEaten = run.score / 10;
return {
  ...run,
  applesEaten,
  applesPerHundredTicks: +(100 * applesEaten / Math.max(1, run.ticks)).toFixed(2),
  verdict: run.diedOn === 'wall' ? 'watch the walls!' : 'stop chasing your own tail!',
};
